mapper.sql:
left join ( select portfolio_id, sec_acct_id, finprod_id, nvl(sum(case when hoding_type = '03' then AMOUNT end),0) PTL_AMOUNT03, nvl(sum(case when hoding_type = '04' then AMOUNT end),0) PTL_AMOUNT04, nvl(sum(case when hoding_type = '05' then AMOUNT end),0) PTL_AMOUNT05, nvl(sum(case when hoding_type = '06' then AMOUNT end),0) PTL_AMOUNT06, nvl(sum(case when hoding_type = '08' then AMOUNT end),0) PTL_AMOUNT08 from PTL_SEC_POSITION where cdate = to_date(#{cdate},'yyyy-MM-dd') /**to_date('2019-10-18','yyyy-MM-dd')**/ /**and t6.hoding_type in ('03', '04', '05', '06','08')**/
#{secHodingType,jdbcType=VARCHAR}
group by portfolio_id, sec_acct_id, finprod_id ) t6 on t6.portfolio_id = t.portfolioId /**and (t6.sec_acct_id = t.secAcctId OR t6.sec_acct_id = '999999')**/ and t6.sec_acct_id = t.conSecAcctId and t6.finprod_id = t.finprodId left join ( select portfolio_id, sec_acct_id, finprod_id, nvl(sum(case when hoding_type = '01' then AMOUNT end),0) PTL_FLOW_AMOUNT01 from PTL_SEC_POSITION_FLOW where cdate <= to_date(#{cdate},'yyyy-MM-dd') /**and cdate = to_date('2019-10-18','yyyy-MM-dd')**/
#{secFlowHodingType,jdbcType=VARCHAR}
group by portfolio_id, sec_acct_id, finprod_id ) t7 on t7.portfolio_id = t.portfolioId /**and (t7.sec_acct_id = t.secAcctId OR t7.sec_acct_id = '999999')**/ and t7.sec_acct_id = t.conSecAcctId and t7.finprod_id = t.finprodId left join ( select A.portfolio_id, A.sec_acct_id, A.finprod_id, nvl(sum(case when A.hoding_type = 'E01' then A.AMOUNT end),0) ETR_FLOW_AMOUNTE01, nvl(sum(case when A.hoding_type = '04' then A.AMOUNT end),0) ETR_FLOW_AMOUNT04 from ETR_SEC_POSITION A INNER JOIN FIN_PRODUCT B ON A.FINPROD_ID=B.FINPROD_ID where A.cdate = to_date(#{cdate},'yyyy-MM-dd') /**and A.cdate = to_date('2019-10-18', 'yyyy-MM-dd')**/ /**and t8.hoding_type in ('E01', '04')**/
#{etrFlowHodingType,jdbcType=VARCHAR}
group by A.portfolio_id, A.sec_acct_id, A.finprod_id ) t8 on t8.portfolio_id = t.portfolioId /**and (t8.sec_acct_id = t.secAcctId OR t8.sec_acct_id = '999999')**/ and t8.sec_acct_id = t.conSecAcctId and t8.finprod_id = t.finprodId /*add by mashukai 20210318 ZGBSS-976 start*/ left join ( SELECT TSF.portfolio_id, TSF.sec_acct_id, TSFT.finprod_id, nvl(sum(decode(TSF.PS,'01',-TSFT.AMT,'02',TSFT.AMT,0)),0) AMT FROM TRD_STASEC_FLOW TSF INNER JOIN TRD_STASEC_FLOW_DETAIL TSFT ON TSF.SEQNO=TSFT.SEQNO WHERE TSF.CDATE = to_date(#{cdate},'yyyy-MM-dd') group by TSF.portfolio_id, TSF.sec_acct_id, TSFT.finprod_id )t9 on t9.portfolio_id = t.portfolioId AND t9.sec_acct_id = t.conSecAcctId AND t9.finprod_id = t.finprodId /*add by mashukai 20210318 ZGBSS-976 end*/

left join ( select portfolio_id, sec_acct_id, finprod_id, nvl(sum(case when hoding_type = '03' then AMOUNT end),0) PTL_AMOUNT03, nvl(sum(case when hoding_type = '04' then AMOUNT end),0) PTL_AMOUNT04, nvl(sum(case when hoding_type = '05' then AMOUNT end),0) PTL_AMOUNT05, nvl(sum(case when hoding_type = '06' then AMOUNT end),0) PTL_AMOUNT06, nvl(sum(case when hoding_type = '08' then AMOUNT end),0) PTL_AMOUNT08 from PTL_SEC_POSITION where cdate = to_date(#{cdate},'yyyy-MM-dd') /**to_date('2019-10-18','yyyy-MM-dd')**/ /**and t6.hoding_type in ('03', '04', '05', '06','08')**/
#{secHodingType,jdbcType=VARCHAR}
group by portfolio_id, sec_acct_id, finprod_id ) t6 on t6.portfolio_id = t.portfolioId /**and (t6.sec_acct_id = t.secAcctId OR t6.sec_acct_id = '999999')**/ and t6.sec_acct_id = t.conSecAcctId and t6.finprod_id = t.finprodId left join ( select portfolio_id, sec_acct_id, finprod_id, nvl(sum(case when hoding_type = '01' then AMOUNT end),0) PTL_FLOW_AMOUNT01 from PTL_SEC_POSITION_FLOW where cdate <= to_date(#{cdate},'yyyy-MM-dd') /**and cdate = to_date('2019-10-18','yyyy-MM-dd')**/
#{secFlowHodingType,jdbcType=VARCHAR}
group by portfolio_id, sec_acct_id, finprod_id ) t7 on t7.portfolio_id = t.portfolioId /**and (t7.sec_acct_id = t.secAcctId OR t7.sec_acct_id = '999999')**/ and t7.sec_acct_id = t.conSecAcctId and t7.finprod_id = t.finprodId left join ( select A.portfolio_id, A.sec_acct_id, A.finprod_id, nvl(sum(case when A.hoding_type = 'E01' then A.AMOUNT end),0) ETR_FLOW_AMOUNTE01, nvl(sum(case when A.hoding_type = '04' then A.AMOUNT end),0) ETR_FLOW_AMOUNT04 from ETR_SEC_POSITION A INNER JOIN FIN_TRADE_PRODUCT B ON A.FINPROD_ID=B.FINPROD_ID where A.cdate = to_date(#{cdate},'yyyy-MM-dd') /**and A.cdate = to_date('2019-10-18', 'yyyy-MM-dd')**/ /**and t8.hoding_type in ('E01', '04')**/
#{etrFlowHodingType,jdbcType=VARCHAR}
group by A.portfolio_id, A.sec_acct_id, A.finprod_id ) t8 on t8.portfolio_id = t.portfolioId /**and (t8.sec_acct_id = t.secAcctId OR t8.sec_acct_id = '999999')**/ and t8.sec_acct_id = t.conSecAcctId and t8.finprod_id = t.finprodId /*add by mashukai 20210318 ZGBSS-976 start*/ left join ( SELECT TSF.portfolio_id, TSF.sec_acct_id, TSFT.finprod_id, nvl(sum(decode(TSF.PS,'01',-TSFT.AMT,'02',TSFT.AMT,0)),0) AMT FROM TRD_STASEC_FLOW TSF INNER JOIN TRD_STASEC_FLOW_DETAIL TSFT ON TSF.SEQNO=TSFT.SEQNO WHERE TSF.CDATE = to_date(#{cdate},'yyyy-MM-dd') group by TSF.portfolio_id, TSF.sec_acct_id, TSFT.finprod_id )t9 on t9.portfolio_id = t.portfolioId AND t9.sec_acct_id = t.conSecAcctId AND t9.finprod_id = t.finprodId /*add by mashukai 20210318 ZGBSS-976 end*/

mapper.select:
select distinct tt.* from ( select portfolioId,portfolioName,secAcctId,secAcctName,finprodId,finprodMarketId,finprodAbbr,type8,type7, (PTL_AMOUNT03 + PTL_AMOUNT05 - PTL_AMOUNT06) as actualPositionAmount, (PTL_FLOW_AMOUNT01 + PTL_AMOUNT03 + PTL_AMOUNT05 - PTL_AMOUNT06 - PTL_AMOUNT04 + PTL_AMOUNT08) as tradePositionAmount, ETR_FLOW_AMOUNTE01 as instructionsAmount, decode(mm.TYPE8,'F03',(PTL_AMOUNT04 - PTL_FLOW_AMOUNT01 - PTL_AMOUNT08 ), 'F09',(PTL_AMOUNT04 - PTL_FLOW_AMOUNT01 - PTL_AMOUNT08 ), ETR_FLOW_AMOUNT04 ) as pledgeAmount, decode(mm.TYPE8,'F03' ,0, 'F09' ,0, (PTL_AMOUNT04 - PTL_FLOW_AMOUNT01 - PTL_AMOUNT08 ) ) as preReductionAmount from ( select portfolioId, portfolioName, secAcctId, secAcctName, finprodId, finprodMarketId, finprodAbbr, type8, type7, nvl(sum(PTL_AMOUNT03),0) as PTL_AMOUNT03, nvl(sum(PTL_AMOUNT04),0) as PTL_AMOUNT04, nvl(sum(PTL_AMOUNT05),0) as PTL_AMOUNT05, nvl(sum(PTL_AMOUNT06),0) as PTL_AMOUNT06, nvl(sum(PTL_AMOUNT08),0) as PTL_AMOUNT08, nvl(sum(PTL_FLOW_AMOUNT01),0) as PTL_FLOW_AMOUNT01, /*标准券出入库的指令可用持仓取标准券入出库表（TRD_STASEC_FLOW）中的持仓*/ decode(TYPE8,'F01',NVL(SUM(ETR_FLOW_AMOUNTE01),0)+ nvl(SUM(AMT),0),NVL(SUM(ETR_FLOW_AMOUNTE01),0)) AS ETR_FLOW_AMOUNTE01, nvl(sum(ETR_FLOW_AMOUNT04),0) as ETR_FLOW_AMOUNT04 from ( select t.portfolio_id as portfolioId, t.portfolio_name as portfolioName, (case when t4.sec_acct_id is null and chnl.finprod_id is null then '' when t4.sec_acct_id is null then chnl.finprod_market_id else t4.sec_acct_id end ) as secAcctId, (case when t4.sec_acct_id is null and chnl.finprod_id is null then '' when t4.sec_acct_id is null then chnl.finprod_abbr else t4.sec_acct_name end ) as secAcctName, /**t4.sec_acct_id as secAcctId,t4.sec_acct_name as secAcctName,**/ chnl.finprod_id as chnlFinprodId, chnl.finprod_market_id as chnlFinprodMarketId, chnl.finprod_abbr as chnlFinprodAbbr, (case when t4.sec_acct_id is null and chnl.finprod_id is null then '999999' when t4.sec_acct_id is null then chnl.finprod_id else t4.sec_acct_id end ) as conSecAcctId, t2.finprod_id as finprodId, nvl(fin.finprod_market_id, t2.finprod_id) as finprodMarketId, nvl(fin.finprod_abbr, t2.finprod_id) as finprodAbbr, t5.type_8 as type8, nvl(t5.type_7, t5.type_6) as type7 from PTL_PORTFOLIO t INNER JOIN PTL_TRADE t3 ON t3.portfolio_id = t.portfolio_id INNER JOIN TRD_PRODUCT_DEAL t2 ON t2.trade_id = t3.BUSI_NO INNER JOIN FIN_PRODUCT fin on fin.finprod_id = t2.finprod_id INNER JOIN fin_product_type t5 on t5.finprod_id = t2.finprod_id left join PTL_SEC_ACCT t1 on t1.portfolio_id = t.portfolio_id and t1.acct_no = t2.sec_manage_acct_id left join STL_SEC_ACCT_INFO t4 on t4.sec_acct_id = t1.acct_no
LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL TOTAL ON t2.TOTLE_TRADE_ID = TOTAL.TOTLE_TRADE_ID left join FIN_PRODUCT chnl on chnl.finprod_id = DECODE( t2.CHL_ID,NULL,TOTAL.CHL_ID, t2.CHL_ID ) /** and chnl.finprod_type2 = 'F28' **/
and chnl.finprod_type2 = #{finprodType2,jdbcType=VARCHAR}
where 1=1
#{item,jdbcType=VARCHAR}
and t5.type_8 = #{type8,jdbcType=VARCHAR}
and t2.finprod_id = #{finprodId,jdbcType=VARCHAR}
#{item,jdbcType=VARCHAR}
#{type8Item,jdbcType=VARCHAR}
#{noshowType8,jdbcType=VARCHAR}
group by t.portfolio_id, t.portfolio_name, t4.sec_acct_id, t4.sec_acct_name, chnl.finprod_id , chnl.finprod_market_id, chnl.finprod_abbr, t2.finprod_id, fin.finprod_market_id, fin.finprod_abbr, t5.type_8, t5.type_7, t5.type_6 ) t
group by portfolioId, portfolioName, secAcctId, secAcctName, finprodId, finprodMarketId, finprodAbbr, type8, type7 union all select portfolioId, portfolioName, secAcctId, secAcctName, '' finprodId, '' finprodMarketId, '' finprodAbbr, type8, type7, nvl(sum(PTL_AMOUNT03),0) as PTL_AMOUNT03, nvl(sum(PTL_AMOUNT04),0) as PTL_AMOUNT04, nvl(sum(PTL_AMOUNT05),0) as PTL_AMOUNT05, nvl(sum(PTL_AMOUNT06),0) as PTL_AMOUNT06, nvl(sum(PTL_AMOUNT08),0) as PTL_AMOUNT08, nvl(sum(PTL_FLOW_AMOUNT01),0) as PTL_FLOW_AMOUNT01, nvl(sum(ETR_FLOW_AMOUNTE01),0) as ETR_FLOW_AMOUNTE01, nvl(sum(ETR_FLOW_AMOUNT04),0) as ETR_FLOW_AMOUNT04 from ( select t.portfolio_id as portfolioId, t.portfolio_name as portfolioName, (case when t4.sec_acct_id is null and chnl.finprod_id is null then '' when t4.sec_acct_id is null then chnl.finprod_market_id else t4.sec_acct_id end ) as secAcctId, (case when t4.sec_acct_id is null and chnl.finprod_id is null then '' when t4.sec_acct_id is null then chnl.finprod_abbr else t4.sec_acct_name end ) as secAcctName, /**t4.sec_acct_id as secAcctId,t4.sec_acct_name as secAcctName,**/ chnl.finprod_id as chnlFinprodId, chnl.finprod_market_id as chnlFinprodMarketId, chnl.finprod_abbr as chnlFinprodAbbr, (case when t4.sec_acct_id is null and chnl.finprod_id is null then '999999' when t4.sec_acct_id is null then chnl.finprod_id else t4.sec_acct_id end ) as conSecAcctId, t2.finprod_id as finprodId, t5.type_8 as type8, nvl(t5.type_7, t5.type_6) as type7 from PTL_PORTFOLIO t INNER JOIN PTL_TRADE t3 ON t3.portfolio_id = t.portfolio_id INNER JOIN TRD_PRODUCT_DEAL t2 ON t2.trade_id = t3.BUSI_NO INNER JOIN FIN_TRADE_PRODUCT fin on (fin.finprod_id = t2.TRADE_ID or (fin.finprod_id = t2.TOTLE_TRADE_ID and fin.finprod_type='F35'))
INNER JOIN fin_product_type t5 on t5.finprod_id = t2.finprod_id left join PTL_SEC_ACCT t1 on t1.portfolio_id = t.portfolio_id and t1.acct_no = t2.sec_manage_acct_id left join STL_SEC_ACCT_INFO t4 on t4.sec_acct_id = t1.acct_no
LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL TOTAL ON t2.TOTLE_TRADE_ID = TOTAL.TOTLE_TRADE_ID left join FIN_PRODUCT chnl on chnl.finprod_id = DECODE( t2.CHL_ID,NULL,TOTAL.CHL_ID, t2.CHL_ID ) /** and chnl.finprod_type2 = 'F28' **/
and chnl.finprod_type2 = #{finprodType2,jdbcType=VARCHAR}
where 1=1
#{item,jdbcType=VARCHAR}
and t5.type_8 = #{type8,jdbcType=VARCHAR}
and t2.finprod_id = #{finprodId,jdbcType=VARCHAR}
#{item,jdbcType=VARCHAR}
#{type8Item,jdbcType=VARCHAR}
#{noshowType8,jdbcType=VARCHAR}
group by t.portfolio_id, t.portfolio_name, t4.sec_acct_id, t4.sec_acct_name, chnl.finprod_id, chnl.finprod_market_id, chnl.finprod_abbr, t2.finprod_id, t5.type_8, t5.type_7, t5.type_6 ) t
group by portfolioId, portfolioName, secAcctId, secAcctName, type8, type7 union all select portfolioId, portfolioName, secAcctId, secAcctName, finprodId, finprodMarketId, finprodAbbr, type8, type7, nvl(sum(PTL_AMOUNT03),0) as PTL_AMOUNT03, nvl(sum(PTL_AMOUNT04),0) as PTL_AMOUNT04, nvl(sum(PTL_AMOUNT05),0) as PTL_AMOUNT05, nvl(sum(PTL_AMOUNT06),0) as PTL_AMOUNT06, nvl(sum(PTL_AMOUNT08),0) as PTL_AMOUNT08, nvl(sum(PTL_FLOW_AMOUNT01),0) as PTL_FLOW_AMOUNT01, nvl(sum(ETR_FLOW_AMOUNTE01),0) as ETR_FLOW_AMOUNTE01, nvl(sum(ETR_FLOW_AMOUNT04),0) as ETR_FLOW_AMOUNT04 from ( select portfolioId, portfolioName, secAcctId, secAcctName, chnlFinprodId, chnlFinprodMarketId, chnlFinprodAbbr, conSecAcctId, finprodId, finprodMarketId, finprodAbbr, type8, type7 from ( select t.portfolio_id as portfolioId, t.portfolio_name as portfolioName, (case when t4.sec_acct_id is null and chnl.finprod_id is null then '' when t4.sec_acct_id is null then chnl.finprod_market_id else t4.sec_acct_id end ) as secAcctId, (case when t4.sec_acct_id is null and chnl.finprod_id is null then '' when t4.sec_acct_id is null then chnl.finprod_abbr else t4.sec_acct_name end ) as secAcctName, /**t4.sec_acct_id as secAcctId,t4.sec_acct_name as secAcctName,**/ chnl.finprod_id as chnlFinprodId, chnl.finprod_market_id as chnlFinprodMarketId, chnl.finprod_abbr as chnlFinprodAbbr, (case when t4.sec_acct_id is null and chnl.finprod_id is null then '999999' when t4.sec_acct_id is null then chnl.finprod_id else t4.sec_acct_id end ) as conSecAcctId, FDP.PLEDGE_FINPROD_ID AS finprodId, fin1.finprod_market_id as finprodMarketId, fin1.finprod_abbr as finprodAbbr, t5.type_8 AS type8, nvl(t5.type_7, t5.type_6) AS type7 FROM PTL_PORTFOLIO t INNER JOIN PTL_TRADE t3 ON t3.portfolio_id = t.portfolio_id INNER JOIN TRD_PRODUCT_DEAL t2 ON t2.trade_id = t3.BUSI_NO INNER JOIN FIN_TRADE_PRODUCT fin ON fin.finprod_id = t2.finprod_id INNER JOIN FIN_DEAL_PLEDGE FDP ON t2.FINPROD_ID = FDP.FINPROD_ID INNER JOIN fin_product_type t5 ON FDP.PLEDGE_FINPROD_ID = t5.finprod_id INNER JOIN FIN_PRODUCT fin1 on fin1.finprod_id = FDP.PLEDGE_FINPROD_ID LEFT JOIN PTL_SEC_ACCT t1 ON t1.portfolio_id = t.portfolio_id AND t1.acct_no = t2.sec_manage_acct_id LEFT JOIN STL_SEC_ACCT_INFO t4 ON t4.sec_acct_id = t1.acct_no
LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL TOTAL ON t2.TOTLE_TRADE_ID = TOTAL.TOTLE_TRADE_ID left join FIN_PRODUCT chnl on chnl.finprod_id = DECODE( t2.CHL_ID,NULL,TOTAL.CHL_ID, t2.CHL_ID ) /** and chnl.finprod_type2 = 'F28' **/
and chnl.finprod_type2 = #{finprodType2,jdbcType=VARCHAR}
where 1=1
#{item,jdbcType=VARCHAR}
and t5.type_8 = #{type8,jdbcType=VARCHAR}
and t2.finprod_id = #{finprodId,jdbcType=VARCHAR}
#{item,jdbcType=VARCHAR}
union all select t.portfolio_id as portfolioId, t.portfolio_name as portfolioName, (case when t4.sec_acct_id is null and chnl.finprod_id is null then '' when t4.sec_acct_id is null then chnl.finprod_market_id else t4.sec_acct_id end ) as secAcctId, (case when t4.sec_acct_id is null and chnl.finprod_id is null then '' when t4.sec_acct_id is null then chnl.finprod_abbr else t4.sec_acct_name end ) as secAcctName, /**t4.sec_acct_id as secAcctId,t4.sec_acct_name as secAcctName,**/ chnl.finprod_id as chnlFinprodId, chnl.finprod_market_id as chnlFinprodMarketId, chnl.finprod_abbr as chnlFinprodAbbr, (case when t4.sec_acct_id is null and chnl.finprod_id is null then '999999' when t4.sec_acct_id is null then chnl.finprod_id else t4.sec_acct_id end ) as conSecAcctId, FDT.PLEDGE_FINPROD_ID AS finprodId, fin1.finprod_market_id as finprodMarketId, fin1.finprod_abbr as finprodAbbr, t5.type_8 AS type8, nvl(t5.type_7, t5.type_6) AS type7 FROM PTL_PORTFOLIO t INNER JOIN PTL_TRADE t3 ON t3.portfolio_id = t.portfolio_id INNER JOIN TRD_PRODUCT_DEAL t2 ON t2.trade_id = t3.BUSI_NO INNER JOIN FIN_TRADE_PRODUCT fin ON fin.finprod_id = t2.finprod_id INNER JOIN FIN_DEAL_TARGET FDT ON T2.FINPROD_ID = FDT.FINPROD_ID INNER JOIN fin_product_type t5 ON FDT.PLEDGE_FINPROD_ID = t5.finprod_id INNER JOIN FIN_PRODUCT fin1 on fin1.finprod_id = FDT.PLEDGE_FINPROD_ID LEFT JOIN PTL_SEC_ACCT t1 ON t1.portfolio_id = t.portfolio_id AND t1.acct_no = t2.sec_manage_acct_id LEFT JOIN STL_SEC_ACCT_INFO t4 ON t4.sec_acct_id = t1.acct_no
LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL TOTAL ON t2.TOTLE_TRADE_ID = TOTAL.TOTLE_TRADE_ID left join FIN_PRODUCT chnl on chnl.finprod_id = DECODE( t2.CHL_ID,NULL,TOTAL.CHL_ID, t2.CHL_ID ) /** and chnl.finprod_type2 = 'F28' **/
and chnl.finprod_type2 = #{finprodType2,jdbcType=VARCHAR}
where 1=1
#{item,jdbcType=VARCHAR}
and t5.type_8 = #{type8,jdbcType=VARCHAR}
and t2.finprod_id = #{finprodId,jdbcType=VARCHAR}
#{item,jdbcType=VARCHAR}
) rrq group by portfolioId, portfolioName, secAcctId, secAcctName, chnlFinprodId, chnlFinprodMarketId, chnlFinprodAbbr, conSecAcctId, finprodId, finprodMarketId, finprodAbbr, type8, type7 ) t
group by portfolioId, portfolioName, secAcctId, secAcctName, finprodId, finprodMarketId, finprodAbbr, type8, type7 ) mm ) tt where actualPositionAmount <> 0 or tradePositionAmount <> 0 or instructionsAmount <> 0 or pledgeAmount <> 0 or preReductionAmount <> 0 order by portfolioId desc,type8 desc,secAcctId desc,finprodMarketId desc

SELECT t.finprod_id object, t.finprod_market_id id, t.finprod_abbr text FROM FIN_PRODUCT t INNER JOIN fin_product_type t1 on t1.finprod_id = t.finprod_id WHERE 1=1 AND t.FINPROD_TYPE2 IN('F01','F02','F11')
and t1.type_8 = #{type8,jdbcType = VARCHAR}
AND (t.finprod_market_id LIKE CONCAT('%',CONCAT(#{search},'%')) OR t.finprod_abbr LIKE CONCAT('%',CONCAT(#{search},'%')))
#{noshowType8,jdbcType=VARCHAR}
UNION ALL SELECT t.finprod_id object, t.finprod_market_id id, t.finprod_abbr text FROM FIN_PRODUCT t INNER JOIN fin_product_type t1 on t1.finprod_id = t.finprod_id
LEFT JOIN DATA_AUTH_NOTIFY_INST dani on dani.BUSINESS_ID = t.finprod_id AND dani.INSTITUTION_CODE=#{institutionCode} LEFT JOIN DATA_AUTH_NOTIFY_INST dani1 on dani.BUSINESS_ID is null and dani1.BUSINESS_ID = t.FINPROD_MARKET_ID AND dani1.INSTITUTION_CODE=#{institutionCode}
WHERE 1=1 AND t.FINPROD_TYPE2 NOT IN('F01','F02','F11')
and (dani.BUSINESS_ID is not null or dani1.BUSINESS_ID is not null)
and t1.type_8 = #{type8,jdbcType = VARCHAR}
AND (t.finprod_market_id LIKE CONCAT('%',CONCAT(#{search},'%')) OR t.finprod_abbr LIKE CONCAT('%',CONCAT(#{search},'%')))
#{noshowType8,jdbcType=VARCHAR}
